//! 🧪️ Genuine original parent, command and SemioFlow child leases authorize an unchanged native batch.
use super::*;
use semio_plugin::app::{MemberKey,ChildContentView,ChildContentEntry,ChildContentReadRetirement,child_read::{*,command::*}};
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,ErasedSnapshotRetirement};
use semio_framework_value::retained_clone::RetainedCloneSource;
use semio_framework_value::retirement::{RetireOwned,controlled::ControlledRetirement,arc_custody};
use semio_os_kernel::os_store::snapshot_read as reads;
use std::sync::Arc;
type Mutation=crate::schema::mutations::SemioFlowMutation;
struct Bank{limit:RetainedCloneGrant,caller:semio_framework_job::OriginalJobFixtureCaller,calls:usize,maximum_work:u64,work_mismatch:bool,publication_calls:usize,owned_close_calls:usize}
fn clock()->Option<u64>{Some(1000)}
impl Bank{
 fn new(stock:RetainedCloneGrant,policy:&serde_json::Value)->Self{Self{limit:stock,caller:semio_framework_job::OriginalJobFixtureCaller::admit(semio_framework_job::OperationId(policy["operation"].as_u64().unwrap()),semio_framework_job::Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap()),calls:0,maximum_work:0,work_mismatch:false,publication_calls:0,owned_close_calls:0}}
 fn grant(&self,d:RetirementDemand)->RetainedCloneGrant{let remaining=self.caller.remaining_grant();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert!(remaining.maximum_items>0);assert!(d.copy_bytes<=remaining.maximum_copy_bytes);assert!(d.capacity_bytes<=remaining.maximum_capacity_bytes);assert!(d.release_bytes<=remaining.maximum_release_bytes);assert!(d.depth<=remaining.maximum_depth);g}
 fn observe<T>(&mut self,g:RetainedCloneGrant,run:impl FnOnce()->(T,RetainedCloneProgress,u64))->T{
  self.calls+=1;let fuel=self.caller.fuel_remaining();let(value,reported)=self.caller.turn(g,|cx|{let deadline=cx.original_absolute_deadline_us();cx.with_original_work_loan(1,deadline,|same|{
   let((value,p,work),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);assert!(!heap.overflowed);assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));
   semio_framework_job::receive_original_retained_work(same,RetainedWorkOutcome::<_,semio_framework_value::ValueError>{result:Ok(RetainedCloneStep::Progress(p)),work})?;Ok((value,work))
  })}).unwrap();let actual=fuel-self.caller.fuel_remaining();self.maximum_work=self.maximum_work.max(reported).max(actual);self.work_mismatch|=actual!=reported;assert!(self.caller.cumulative_receipt().fits(self.limit));value
 }
 fn source<T:RetireOwned+Sync>(&mut self,input:T)->RetainedCloneSource<T>{
  let mut admission=semio_framework_value::retained_clone::RetainedCloneSourceAdmission::<T,T>::new(input,(),|value|value);let mut output=None;
  for _ in 0..1000{if output.is_some(){assert!(admission.terminal_is_empty());return output.take().unwrap()}let d=if admission.phase()=="ready"{RetirementDemand{depth:1,..Default::default()}}else{admission.next_demand().unwrap()};let g=self.grant(d);self.observe(g,||{let turn=if admission.phase()=="ready"{admission.take_output(&mut output,g)}else{admission.advance(g)};let work=turn.work;let p=turn.result.unwrap().progress();((),p,work)});}
  panic!("actual source admission must reach its original output")
 }
 fn retire<T:RetireOwned>(&mut self,value:T){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("native batch fixture owner has exact retirement"));for _ in 0..100000{if owner.terminal_is_empty(){return}let g=self.grant(owner.selected_demand(64).unwrap());self.observe(g,||{let step=owner.step(g).unwrap();((),step.progress(),owner.last_turn_work())});}panic!("native batch original owner did not close")}
 fn finish(mut self){while !self.caller.terminal_is_empty(){self.calls+=1;let d=self.caller.retirement_demands().unwrap();let g=self.grant(d);let before=self.caller.fuel_remaining();self.caller.retire_step(g).unwrap();self.maximum_work=self.maximum_work.max(before-self.caller.fuel_remaining());}assert_eq!(self.caller.stock(),self.limit);assert!(self.caller.cumulative_receipt().fits(self.limit));assert!(!self.work_mismatch,"actual initiating caller fuel differs from producer work");assert!(self.maximum_work<=1,"a child pipeline event exceeded its actual one-fuel frame");assert!(self.calls<=200,"whole child component fixture used {} calls (publication {}, owned close {})",self.calls,self.publication_calls,self.owned_close_calls);}
}
#[derive(semio_framework_value::RetireOwned)]struct Parent{child_id:String,artifact_id:String}
struct Lender;
static LENDER:Lender=Lender;
impl ChildReadReferenceLenderV1 for Lender{
 fn demand(&self,_:usize)->RetirementDemand{RetirementDemand{copy_bytes:2*std::mem::size_of::<RetainedWorkOutcome<ChildReadReferenceAdvance<'static>>>(),depth:1,..Default::default()}}
 fn read<'a>(&self,source:ChildAdmissionSource<'a>,ordinal:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<ChildReadReferenceAdvance<'a>>{
  let d=self.demand(ordinal);if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(ChildReadReferenceAdvance{progress:Default::default(),done:false,reference:None}),work:0}}
  let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};let result=(||{let parent=source.get().downcast_ref::<Parent>().ok_or_else(||semio_framework_value::ValueError::invariant("original SemioFlow parent type changed").with_retained_progress(p))?;if ordinal!=0{return Err(semio_framework_value::ValueError::invariant("original SemioFlow member ordinal changed").with_retained_progress(p))}Ok(ChildReadReferenceAdvance{progress:p,done:true,reference:Some(ChildReadReference{parent_identity:parent as*const _ as usize,identity:&parent.child_id as*const _ as usize,owner:"",slot:"content",child_id:&parent.child_id,artifact_id:&parent.artifact_id,artifact_kind:SEMIO_FLOW_DIALECT.artifact_kind,standard:SEMIO_FLOW_DIALECT.standard.0,subset:SEMIO_FLOW_DIALECT.subset.0})})})();RetainedWorkOutcome{result,work:1}
 }
}
#[test]
fn native_semio_flow_registration_has_exact_identity_and_no_vector_extension(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 assert_eq!(SEMIO_FLOW_CHILD_EDITOR_ID,semio_framework::surface_app_id(&SEMIO_FLOW_DIALECT.into(),semio_framework::AppRole::Editor));
 assert_eq!(fixture["artifactKind"],SEMIO_FLOW_CHILD_READ.identity.artifact_kind);assert_eq!(fixture["standard"],SEMIO_FLOW_CHILD_READ.identity.standard);assert_eq!(fixture["subset"],SEMIO_FLOW_CHILD_READ.identity.subset);assert_eq!(fixture["editorId"],SEMIO_FLOW_CHILD_EDITOR_ID);assert_eq!(fixture["command"],SEMIO_FLOW_APPLY_MUTATIONS_COMMAND_ID);assert!(SEMIO_FLOW_CHILD_APPLY_MUTATIONS.vector_services().is_err());assert_eq!(fixture["mutations"],serde_json::json!(crate::schema::mutations::KINDS));
}
#[test]
fn native_original_semio_flow_batches_preserve_qualified_custody_pointer_and_heap(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/📜️declaration/📨️emission/🛬️lifted/📦️preparation/🪢️batch/🔣️.json")).unwrap();let policy:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🧪️testing/🎟️caller/🧪️tests/🧫️fixtures/🎟️caller.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();
 for row in corpus["cases"].as_array().unwrap(){
  let mut operations=Some(row["values"].as_array().unwrap().iter().map(|value|Mutation::SetNodeLabel(crate::schema::mutations::set_node_label::SetNodeLabel{id:format!("n{}",value.as_u64().unwrap()),label:value.to_string()})).collect::<Vec<_>>());let pointer=operations.as_ref().unwrap().as_ptr();let capacity=operations.as_ref().unwrap().capacity();let expected=serde_json::Value::Array(row["values"].as_array().unwrap().iter().map(|value|serde_json::json!({"mutation":"setNodeLabel","id":format!("n{}",value.as_u64().unwrap()),"label":value.to_string()})).collect());
  let command=String::from("original graph edit command");let mut bank=Bank::new(stock,&policy);
  let child_id=String::from("flow:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");assert_eq!(child_id.len(),77);let parent_value=Parent{child_id:child_id.clone(),artifact_id:"original SemioFlow child".into()};
  let mut parent=bank.source(parent_value);let mut command=bank.source(command);
  let registry=reads::SnapshotReadRegistryHandle::new();assert!(registry.publish_authority(17,[42;32]));let payload=Arc::new(SemioFlowSnapshot::default());let lease=registry.try_issue(Arc::clone(&payload)).unwrap_or_else(|_|panic!("genuine original SemioFlow child issuer"));let key=MemberKey::root("content",&child_id);let index=ChildContentView::hash(key.borrowed()).unwrap();let view=ChildContentView::EMPTY.insert_entry_admitted(index,ChildContentEntry{owner:String::new(),slot:key.slot.clone(),child_id:key.child_id.clone(),artifact_id:"original SemioFlow child".into(),dialect:SEMIO_FLOW_DIALECT.into(),revision:[42;32],snapshot:reads::ErasedSnapshotRead::new(Arc::clone(&payload),lease)});
  let operation=semio_plugin::AppOperationContext{app_instance_id:4,parent_document_id:"original Flow parent".into(),operation_id:policy["operation"].as_u64().unwrap(),generation:policy["generation"].as_u64().unwrap(),canonical_base_revision:[31;32],retained:stock,authoring_seed:"native-batch-fixture".into()};
  let g=bank.grant(OriginalChildMemberLookup::birth_demand());let mut lookup=bank.observe(g,||{let(owner,p)=OriginalChildMemberLookup::admit(g).unwrap();(owner,p,1)});
  let read=loop{let g=bank.grant(lookup.demand::<SemioFlowSnapshot>());let result=bank.observe(g,||{let result=SEMIO_FLOW_CHILD_READ.read_original(parent.borrow(),&view,key.borrowed(),&operation,&mut lookup,g).unwrap();let p=result.progress;(result,p,lookup.last_turn_work())});if let Some(read)=result.read{break read}};
  assert_eq!(&*read.read as*const SemioFlowSnapshot,Arc::as_ptr(&payload));
  let g=bank.grant(ChildReadCursor::birth_demand());let mut cursor=bank.observe(g,||{let(owner,p)=ChildReadCursor::admit(g).unwrap();(owner,p,1)});
  let stamp=loop{let source=erase_child_admission_source(parent.borrow(),0x53464c4f);let g=bank.grant(cursor.next_demand(source,&LENDER,0,&read,&SEMIO_FLOW_CHILD_READ.identity).unwrap());let result=bank.observe(g,||{let result=SEMIO_FLOW_CHILD_READ.qualify(source,&LENDER,0,&read,&mut cursor,g).unwrap();let p=result.progress;(result,p,cursor.last_turn_work())});if let Some(stamp)=result.stamp{break stamp}};
  let mut custody=ChildReadSourceCustody::new();while !custody.ready(){let g=bank.grant(custody.next_admit_demand().unwrap());bank.observe(g,||{let p=SEMIO_FLOW_CHILD_READ.admit_original_source(&read,&stamp,&mut custody,g).unwrap().progress();((),p,custody.last_turn_work())});}
  let g=bank.grant(OriginalChildEditorCommandCursor::birth_demand());let mut qualifier=bank.observe(g,||{let(owner,p)=OriginalChildEditorCommandCursor::admit(g).unwrap();(owner,p,1)});
  loop{let g=bank.grant(qualifier.next_demand().unwrap());let result=bank.observe(g,||{let result=SEMIO_FLOW_CHILD_APPLY_MUTATIONS.qualify_original(parent.borrow(),command.borrow(),&stamp,&read,&mut qualifier,g).unwrap();let p=result.progress;(result,p,qualifier.last_turn_work())});if result.stamp.is_some(){break}}
  let mut authority=Some(loop{let g=bank.grant(qualifier.take_authority_demand().unwrap());let authority=bank.observe(g,||{let turn=qualifier.take_authority(&custody,&read,g);let work=turn.work;let step=turn.result.unwrap();(step.authority,step.progress,work)});if let Some(authority)=authority{break authority}});assert!(qualifier.terminal_is_empty());assert_eq!(authority.as_ref().unwrap().parent_source_identity(),Some(parent.borrow().reference_identity()));assert_eq!(authority.as_ref().unwrap().command_source_identity(),Some(command.borrow().reference_identity()));
  let d=semio_flow_mutation_batch_demand("content".len(),key.child_id.len()).unwrap();let g=bank.grant(d);
  for axis in 0..5{let mut denied=g;let selected=match axis{0=>&mut denied.maximum_items,1=>&mut denied.maximum_copy_bytes,2=>&mut denied.maximum_capacity_bytes,3=>&mut denied.maximum_release_bytes,_=>&mut denied.maximum_depth};if *selected==0{continue}*selected-=1;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||admit_semio_flow_mutation_batch("content",&key.child_id,&mut operations,&mut authority,denied));assert!(result.unwrap().is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(operations.as_ref().unwrap().as_ptr(),pointer);assert_eq!(operations.as_ref().unwrap().capacity(),capacity);assert!(authority.as_ref().unwrap().stamp().is_some());}
  if row["admitted"].as_bool().unwrap(){
   let mut original=Some(bank.observe(g,||{let(owner,p)=admit_semio_flow_mutation_batch("content",&key.child_id,&mut operations,&mut authority,g).unwrap().unwrap();(owner,p,1)}));assert!(operations.is_none()&&authority.is_none());
   let identity=original.as_ref().unwrap().source_window_identity::<Mutation>().unwrap();assert_eq!(identity,(pointer as usize,row["values"].as_array().unwrap().len(),capacity*std::mem::size_of::<Mutation>()));
   let mut emit=semio_plugin::Emit::<Mutation>::default();
   while original.is_some(){
    let g=bank.grant(emit.child_preparation_admission_demands().unwrap());
    for axis in 0..5{let mut denied=g;let selected=match axis{0=>&mut denied.maximum_items,1=>&mut denied.maximum_copy_bytes,2=>&mut denied.maximum_capacity_bytes,3=>&mut denied.maximum_release_bytes,_=>&mut denied.maximum_depth};if *selected==0{continue}*selected-=1;bank.observe(denied,||{let turn=emit.admit_child_preparation_original(&mut original,denied);assert_eq!(turn.work,0);let p=turn.result.unwrap().progress();assert_eq!(p,Default::default());((),p,turn.work)});assert_eq!(original.as_ref().unwrap().source_window_identity::<Mutation>(),Some(identity));assert!(emit.child_preparations.is_empty());}
    bank.observe(g,||{let turn=emit.admit_child_preparation_original(&mut original,g);let work=turn.work;let p=turn.result.unwrap().progress();((),p,work)});
   }
   assert_eq!(emit.child_preparations.front().unwrap().source_window_identity::<Mutation>(),Some(identity));
   loop{let g=bank.grant(emit.child_preparation_demands(64).unwrap());let ready=bank.observe(g,||{let turn=emit.prepare_child_original(g);let work=turn.work;let step=turn.result.unwrap();let ready=matches!(step,semio_plugin::ChildEmitPreparationStep::Ready(_));(ready,step.progress(),work)});if ready{break}}
   assert!(emit.child_preparations.is_empty());assert_eq!(emit.owned_child_emits.len(),1);assert!(emit.child_emits.is_empty());let output=&emit.owned_child_emits[0];let values=output.mutations::<Mutation>().unwrap();assert_eq!(values.as_ptr(),pointer);assert_eq!(values.len(),row["expected"].as_array().unwrap().len());let actual:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(&values)).unwrap();assert_eq!(actual,expected);assert!(output.authority().unwrap().stamp().is_some());bank.publication_calls=bank.calls;bank.retire(emit);

  }else{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||admit_semio_flow_mutation_batch("content",&key.child_id,&mut operations,&mut authority,g));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(operations.as_ref().unwrap().is_empty());bank.publication_calls=bank.calls;bank.retire(operations.take().unwrap());bank.retire(authority.take().unwrap());}
  drop(read);bank.retire(custody);bank.retire(cursor);bank.retire(lookup);bank.retire(command);bank.retire(parent);
  bank.owned_close_calls=bank.calls;let mut child_close=ChildContentReadRetirement::new(view);while !child_close.terminal_is_empty(){let g=bank.grant(child_close.demands(64).unwrap());bank.observe(g,||{let p=child_close.step(g).unwrap().progress();((),p,child_close.last_turn_work())});}
  let mut active=None;while registry.has_returned()||active.is_some(){if active.is_some(){let g=bank.grant(reads::artifact_retirement_box_demands(active.as_ref().unwrap(),64).unwrap());bank.observe(g,||{let turn=reads::artifact_retirement_box_close_step(&mut active,g);let work=turn.work;let p=turn.result.unwrap().progress();((),p,work)});}else{let g=bank.grant(RetirementDemand{capacity_bytes:arc_custody::shared_retirement_birth_bytes::<SemioFlowSnapshot>(),depth:1,..Default::default()});bank.observe(g,||{let turn=registry.try_admit_one_returned::<SemioFlowSnapshot,_>(g,|root,g|arc_custody::admit_shared_retirement(root,g,true));let work=turn.work;let(owner,p)=turn.result.unwrap_or_else(|_|panic!("actual returned SemioFlow read"));active=owner;((),p,work)});}}
  bank.retire(payload);let mut issuer=reads::SnapshotReadRegistryAliasRetirement::new(registry);while !issuer.terminal_is_empty(){let g=bank.grant(issuer.next_demand(64).unwrap());bank.observe(g,||{let turn=issuer.close_step(g);let work=turn.work;let p=turn.result.unwrap().progress();((),p,work)});}bank.finish();
 }
}

#[test]
fn native_original_semio_flow_plain_preview_preserves_header_denial_pointer_and_order(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/📜️declaration/📨️emission/🧪️admission/🪞️preview.json")).unwrap();
 let policy:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🧪️testing/🎟️caller/🧪️tests/🧫️fixtures/🎟️caller.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();
 let operations=fixture["values"].as_array().unwrap().iter().map(|value|Mutation::SetNodeLabel(crate::schema::mutations::set_node_label::SetNodeLabel{id:format!("n{}",value.as_u64().unwrap()),label:value.to_string()})).collect::<Vec<_>>();
 let identity=(operations.as_ptr() as usize,operations.len(),operations.capacity()*std::mem::size_of::<Mutation>());
 let expected_wire=operations.iter().map(|value|semio_os_kernel::OpBinary::encode_op(value).unwrap()).collect::<Vec<_>>();
 let expected_json=serde_json::Value::Array(fixture["expected"]["values"].as_array().unwrap().iter().map(|value|serde_json::json!({"mutation":"setNodeLabel","id":format!("n{}",value.as_u64().unwrap()),"label":value.to_string()})).collect());
 let child_id=String::from("flow:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");assert_eq!(child_id.len(),77);
 let mut original=Some(semio_plugin::ChildEmitPreparation::of_owned::<SemioFlowSnapshot,Mutation>("content",child_id.clone(),operations));
 let mut bank=Bank::new(stock,&policy);let mut emit=semio_plugin::Emit::<Mutation>::default();
 while original.is_some(){let g=bank.grant(emit.child_preparation_admission_demands().unwrap());bank.observe(g,||{let turn=emit.admit_child_preparation_original(&mut original,g);let work=turn.work;let p=turn.result.unwrap().progress();((),p,work)});}
 assert_eq!(emit.child_preparations.front().unwrap().source_window_identity::<Mutation>(),Some(identity));
 let header=emit.child_preview_preparation_demands(64).unwrap();assert!(header.copy_bytes>0);assert_eq!((header.capacity_bytes,header.release_bytes),(0,0));let g=bank.grant(header);
 for axis in 0..5{let mut denied=g;let selected=match axis{0=>&mut denied.maximum_items,1=>&mut denied.maximum_copy_bytes,2=>&mut denied.maximum_capacity_bytes,3=>&mut denied.maximum_release_bytes,_=>&mut denied.maximum_depth};if *selected==0{continue}*selected-=1;bank.observe(denied,||{let turn=emit.prepare_child_preview_original(denied);assert_eq!(turn.work,0);let p=turn.result.unwrap().progress();assert_eq!(p,Default::default());((),p,turn.work)});assert_eq!(emit.child_preparations.front().unwrap().source_window_identity::<Mutation>(),Some(identity));assert_eq!(emit.child_preview_preparation_demands(64).unwrap(),header);assert!(emit.child_emits.is_empty()&&emit.owned_child_emits.is_empty());}
 bank.observe(g,||{let turn=emit.prepare_child_preview_original(g);assert_eq!(turn.work,fixture["expected"]["headerWork"].as_u64().unwrap());let p=turn.result.unwrap().progress();assert_eq!((p.retained_capacity_bytes,p.released_bytes),(0,0));assert_eq!(p.copied_bytes,header.copy_bytes);((),p,turn.work)});
 assert_eq!(emit.child_preparations.front().unwrap().source_window_identity::<Mutation>(),Some(identity));assert!(emit.child_preparations.front().unwrap().preview_demands().is_none());
 loop{let g=bank.grant(emit.child_preview_preparation_demands(64).unwrap());let ready=bank.observe(g,||{let turn=emit.prepare_child_preview_original(g);let work=turn.work;let step=turn.result.unwrap();let ready=matches!(step,semio_plugin::ChildEmitPreparationStep::Ready(_));(ready,step.progress(),work)});if ready{break}}
 assert!(emit.owned_child_emits.is_empty());assert_eq!(emit.child_emits.len(),1);let output=&emit.child_emits[0];assert_eq!(output.slot,"content");assert_eq!(output.child_id,child_id);assert_eq!(output.ops,expected_wire);
 let decoded=output.ops.iter().map(|bytes|<Mutation as semio_os_kernel::OpBinary>::decode_op(bytes).unwrap()).collect::<Vec<_>>();let actual_json:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(&decoded)).unwrap();assert_eq!(actual_json,expected_json);drop(decoded);
 bank.publication_calls=bank.calls;bank.retire(emit);bank.owned_close_calls=bank.calls;bank.finish();
}
